package vn.rtr.aeris.mission;
import android.app.Activity;import android.webkit.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.net.*;
/** Native input clock/foreground producer. It never grants flight authority.
 * Only the owned companion may qualify the original Android clock bracket and
 * verify the active profile/session before accepting a sample.
 */
public final class NativeInputBridge implements AutoCloseable {
 private static final java.util.concurrent.atomic.AtomicLong PRODUCER_SEQUENCE=new java.util.concurrent.atomic.AtomicLong();
 public static final String PROCESS_EPOCH=UUID.randomUUID().toString().replace("-","");
 private final Activity activity;private final WebView web;private final AtomicInteger ioReservations=new AtomicInteger();private volatile JSONObject queuedOriginalRelease;private volatile String terminalReleaseUnknown;
 private final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(1));
 private final java.security.KeyPair producerKey;private final InputJournal journal;private volatile JSONObject clockReceipt;private FlightPads pads;public void setPads(FlightPads value){pads=value;}private volatile boolean foreground,focused,closed,failed;private volatile HttpURLConnection connection;private long sequence,deferredPolls;private volatile JSONObject selected;
 NativeInputBridge(Activity a,WebView w)throws IOException{activity=a;web=w;journal=new InputJournal(a.getFilesDir(),UUID.randomUUID().toString().replace("-",""));try{java.security.KeyPairGenerator generator=java.security.KeyPairGenerator.getInstance("EC");generator.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));producerKey=generator.generateKeyPair();}catch(Exception e){try{journal.close();}catch(IOException ignored){}throw new IOException("SIM_PRODUCER_KEY_INIT",e);}}
 public void navigationRetired(){selected=null;clockReceipt=null;if(!closed)failed=true;if(pads!=null)pads.enabled(false);}
 public void focus(boolean value){focused=value;if(!value){selected=null;if(!closed)failed=true;if(pads!=null)pads.enabled(false);}}
 public void foreground(boolean value){foreground=value;if(!value){selected=null;if(!closed)failed=true;if(pads!=null)pads.enabled(false);}}
 private String signed(JSONObject payload)throws Exception{byte[] raw=payload.toString().getBytes(StandardCharsets.UTF_8);java.security.Signature signer=java.security.Signature.getInstance("SHA256withECDSA");signer.initSign(producerKey.getPrivate());signer.update("AERIS_SIM_NATIVE_INPUT_V1\n".getBytes(StandardCharsets.US_ASCII));signer.update(raw);return new JSONObject().put("format","aeris-native-input-signed-envelope").put("version",1).put("algorithm","SHA256withECDSA").put("keyId",WorkspaceStore.sha(producerKey.getPublic().getEncoded())).put("payloadBase64",java.util.Base64.getEncoder().encodeToString(raw)).put("signatureBase64",java.util.Base64.getEncoder().encodeToString(signer.sign())).toString();}
 private boolean trusted(){return foreground&&focused&&!closed&&web.getUrl()!=null&&web.getUrl().matches("http://127\\.0\\.0\\.1:8896(?:/.*)?");}
 @JavascriptInterface public String clock(String nonce){try{if(nonce==null||!nonce.matches("[a-f0-9]{32}"))throw new IOException("INPUT_CLOCK_NONCE");return signed(new JSONObject().put("format","aeris-android-input-clock").put("version",1).put("nonce",nonce).put("processEpoch",PROCESS_EPOCH).put("pid",android.os.Process.myPid()).put("observedElapsedNs",SystemClock.elapsedRealtimeNanos()).put("foreground",foreground).put("authorityRestorable",false));}catch(Exception e){return "{}";}}
 @JavascriptInterface public void configure(String raw){activity.runOnUiThread(()->{try{if(!trusted()||raw==null||raw.getBytes(StandardCharsets.UTF_8).length>8192)throw new IOException("INPUT_CONFIG_SCOPE");JSONObject q=new JSONObject(raw);if(q.length()!=12)throw new IOException("INPUT_EXACT_CONFIG_FIELDS");for(String k:new String[]{"run","epoch","boot","operator","generation"})if(!q.getString(k).matches("[A-Za-z0-9_.:-]{1,128}"))throw new IOException("INPUT_EXACT_CONTEXT");if(!q.getBoolean("simulationOnly")||q.getBoolean("authorityRestorable")||!"WORKBENCH_SIM_V1".equals(q.getString("profileId"))||!q.getString("processEpoch").equals(PROCESS_EPOCH)||!q.getString("missionSHA256").matches("[a-f0-9]{64}")||!q.getString("grantId").matches("[A-Za-z0-9_.:-]{1,128}")||!q.getString("csrf").matches("[a-f0-9]{48}"))throw new IOException("INPUT_EXPLICIT_PROFILE_SESSION");clockReceipt=null;selected=new JSONObject(q.toString());failed=false;if(pads!=null)pads.enabled(true);}catch(Exception e){selected=null;failed=true;android.util.Log.e("AERIS_PRODUCT_INPUT",e.getMessage());}});}
 /** Called by native touch overlay only, with the original MotionEvent's uptime.
  * There is intentionally no JavascriptInterface motion/action method.
  */
 public void nativeTouch(double roll,double pitch,double throttle,double yaw,long originalEventUptimeMs,String sampleKind,String pointers,String motionCause){
  if(Looper.myLooper()!=Looper.getMainLooper())throw new IllegalStateException("INPUT_ORIGINAL_UI_THREAD");
  if(!trusted()||failed||selected==null||!activity.getWindow().getDecorView().hasWindowFocus())return;
  long frameAt=pads==null?0:pads.frameAckNs();if(frameAt<=0||SystemClock.elapsedRealtimeNanos()-frameAt>200000000L){fail("INPUT_UI_FRAME_ACK_200MS");return;}
  if(originalEventUptimeMs<=0||!("NATIVE_ANDROID_POINTER_STATE_SAMPLE".equals(sampleKind)||"NATIVE_ANDROID_POINTER_RELEASE".equals(sampleKind))){fail("INPUT_ORIGINAL_TOUCH_CAUSE");return;}
  double[] axes={roll,pitch,throttle,yaw};for(double x:axes)if(!Double.isFinite(x)||x< -1||x>1){fail("INPUT_AXES");return;}
  final boolean terminal="NATIVE_ANDROID_POINTER_RELEASE".equals(sampleKind)||"PARTIAL_POINTER_RELEASE".equals(motionCause);int reservation=0;for(int attempt=0;attempt<4;attempt++){int n=ioReservations.get();if(n==0&&ioReservations.compareAndSet(0,1)){reservation=1;break;}if(terminal&&n==1&&ioReservations.compareAndSet(1,2)){reservation=2;break;}if(n>=2||!terminal)break;}if(reservation==0){deferredPolls++;if(terminal)fail("INPUT_TERMINAL_SLOT_FULL_UNKNOWN_LEASE_MUST_EXPIRE");return;}final boolean priority=reservation==2;
  try{final JSONObject q=new JSONObject(selected.toString());q.put("format","aeris-native-pad-sample").put("version",1).put("sequence",sequence=PRODUCER_SEQUENCE.incrementAndGet()).put("axes",new JSONArray(axes)).put("sourceKind",sampleKind).put("motionCause",motionCause).put("mapping",new JSONObject(pads.mappingSnapshot())).put("activePointerIds",new JSONArray(pointers)).put("processEpoch",PROCESS_EPOCH).put("pid",android.os.Process.myPid()).put("clockReceipt",clockReceipt==null?JSONObject.NULL:new JSONObject(clockReceipt.toString())).put("observedElapsedNs",SystemClock.elapsedRealtimeNanos()).put("originalEventUptimeMs",originalEventUptimeMs).put("queuedUptimeMs",SystemClock.uptimeMillis()).put("uiFrameAckElapsedNs",frameAt).put("authorityRestorable",false);if(priority)queuedOriginalRelease=q;io.execute(()->{try{if(!foreground||closed||failed){if(terminal)retainTerminalUnknown(q,"PRIOR_IO_OR_CONTEXT_UNKNOWN");throw new IOException("INPUT_CONTEXT_CLOSED_BEFORE_SEND");}send(q);}catch(Exception e){if(terminal)retainTerminalUnknown(q,e.getMessage());fail(e.getMessage());}finally{if(priority)queuedOriginalRelease=null;ioReservations.decrementAndGet();if(closed&&ioReservations.get()==0)try{journal.close();}catch(IOException e){failed=true;}}});}catch(Exception e){ioReservations.decrementAndGet();fail(e.getMessage());}
 }
 private void send(JSONObject q)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:8896/api/product/native-input").openConnection();connection=c;try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(200);c.setReadTimeout(200);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Origin","http://127.0.0.1:8896");c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("X-Field-CSRF",q.getString("csrf"));q.remove("csrf");q.put("nativeJournalGeneration",journal.generation()).put("nativeJournalIntentSequence",journal.nextSequence());byte[] b=signed(q).getBytes(StandardCharsets.UTF_8);if(b.length>2500)throw new IOException("INPUT_SIGNED_ENVELOPE2500_BEFORE_JOURNAL_TX");journal.append("NATIVE_INPUT_INTENT",SystemClock.elapsedRealtimeNanos(),b);c.setFixedLengthStreamingMode(b.length);try(OutputStream out=c.getOutputStream()){JSONObject active=selected;if(!foreground||!focused||closed||failed||active==null||!active.getString("grantId").equals(q.getString("grantId")))throw new IOException("INPUT_CONTEXT_CHANGED_AT_WRITE");out.write(b);}int code=c.getResponseCode();journal.append("NATIVE_INPUT_HTTP_OUTCOME",SystemClock.elapsedRealtimeNanos(),Integer.toString(code).getBytes(StandardCharsets.US_ASCII));if(code!=200)throw new IOException("INPUT_REJECTED_OR_UNKNOWN_NO_RETRY");try(InputStream in=c.getInputStream()){JSONObject r=new JSONObject(new String(WorkspaceStore.read(in,4096),StandardCharsets.UTF_8));if(!r.getBoolean("ok")||r.getBoolean("authorityRestorable"))throw new IOException("INPUT_NOT_ACKNOWLEDGED");if(r.has("clockChallenge")){JSONObject challenge=r.getJSONObject("clockChallenge");if(!challenge.getString("nonce").matches("[a-f0-9]{32}")||!challenge.getString("processEpoch").equals(PROCESS_EPOCH)||!challenge.getString("grantId").equals(q.getString("grantId")))throw new IOException("INPUT_CLOCK_CHALLENGE_CONTEXT");clockReceipt=new JSONObject().put("challenge",challenge).put("receivedElapsedNs",SystemClock.elapsedRealtimeNanos());}}}finally{c.disconnect();connection=null;}}
 private void retainTerminalUnknown(JSONObject q,String reason){try{JSONObject original=new JSONObject(q.toString());original.put("terminalRetention","UNKNOWN_NOT_DISPATCHED_AFTER_PRIOR_IO").put("unknownReason",String.valueOf(reason));terminalReleaseUnknown=signed(original);}catch(Exception e){terminalReleaseUnknown="{\"retentionFailed\":true}";}}
 private void fail(String reason){failed=true;selected=null;activity.runOnUiThread(()->{if(pads!=null)pads.enabled(false);});android.util.Log.e("AERIS_PRODUCT_INPUT",String.valueOf(reason));}
 @JavascriptInterface public void closeForReview(){activity.runOnUiThread(()->{if(!trusted())return;if(pads!=null)pads.enabled(false);close();});}
 public String snapshot(){try{return new JSONObject().put("processEpoch",PROCESS_EPOCH).put("producerKeyId",WorkspaceStore.sha(producerKey.getPublic().getEncoded())).put("producerPublicKeyX509Base64",java.util.Base64.getEncoder().encodeToString(producerKey.getPublic().getEncoded())).put("producerSignatureAlgorithm","SHA256withECDSA").put("producerIdentityScope","EPHEMERAL_SIM_PROCESS_NOT_PHYSICAL_HID_ATTESTATION").put("foreground",foreground).put("closed",closed&&io.isTerminated()&&ioReservations.get()==0).put("closeRequested",closed).put("workerTerminated",io.isTerminated()).put("failed",failed).put("pending",ioReservations.get()>0).put("deferredStateSamplePolls",deferredPolls).put("ioReservations",ioReservations.get()).put("terminalReleaseUnknown",terminalReleaseUnknown==null?JSONObject.NULL:new JSONObject(terminalReleaseUnknown)).put("journal",new JSONObject(journal.state())).put("layout",new JSONObject(pads==null?"{}":pads.layoutSnapshot())).put("sequence",sequence).put("configured",selected!=null).put("authorityRestorable",false).toString();}catch(Exception e){return "{}";}}
 public void close(){closed=true;foreground=false;focused=false;selected=null;HttpURLConnection c=connection;if(c!=null)c.disconnect();java.util.List<Runnable> cancelled=io.shutdownNow();if(!cancelled.isEmpty()){JSONObject original=queuedOriginalRelease;if(original!=null)retainTerminalUnknown(original,"CLOSE_CANCELLED_QUEUED_TERMINAL");ioReservations.addAndGet(-cancelled.size());}if(ioReservations.get()==0)try{journal.close();}catch(IOException e){failed=true;}}
}
